
window.VERDICT_V_INVENTORY=Object.freeze({version:'1.0.0',mode:'local',aiEnabled:false,apiEndpoint:'/api/v-client-api.php',customerContextAllowed:false});
function veraInventorySeason(date){var d=date instanceof Date?date:new Date(),m=d.getMonth()+1,j=d.getDate();if(m===2&&j>=11&&j<=17)return 'saint-valentin';if(m===7&&j>=15&&j<=21)return 'ete';if((m===10&&j>=28)||(m===11&&j<=3))return 'octobre';if(m===12&&j>=20&&j<=26)return 'noel';return 'standard'}
var VERA_INVENTORY_STANDARD='data:image/webp;base64,';
function veraInventoryApplySeason(){
  var season=veraInventorySeason(new Date()),desired=({"standard": "data:image/webp;base64,", "ete": "data:image/webp;base64,", "noel": "data:image/webp;base64,", "octobre": "data:image/webp;base64,", "saint-valentin": "data:image/webp;base64,"})[season]||VERA_INVENTORY_STANDARD;
  document.querySelectorAll('[data-vera-inventory-avatar]').forEach(function(el){
    el.src=VERA_INVENTORY_STANDARD;el.dataset.veraSeason=season;el.dataset.veraAssetStatus='embedded-fallback';
    if(typeof Image!=='function')return;
    var probe=new Image();
    probe.onload=function(){el.onerror=function(){this.onerror=null;this.src=VERA_INVENTORY_STANDARD;this.dataset.veraAssetStatus='embedded-fallback'};el.src=desired;el.dataset.veraAssetStatus='seasonal-local';try{if(window.VeraLife)window.VeraLife.scan(el.parentElement||el)}catch(e){}};
    probe.onerror=function(){el.src=VERA_INVENTORY_STANDARD;el.dataset.veraAssetStatus='embedded-fallback'};
    probe.src=desired;
  });
}
function vInvStats(){
  var rows=[];try{rows=siteRows(DB.site);}catch(e){}var counted=0,priced=0,first=null,orders=0,missingQty=0,missingPrice=0;
  rows.forEach(function(x){if(x.p.stock!=null)counted++;else{missingQty++;if(!first)first=x;}if(num(x.p.price)>0)priced++;else missingPrice++;try{if(state(x.p).need>0)orders++;}catch(e){}});
  return {rows:rows,counted:counted,priced:priced,first:first,orders:orders,missingQty:missingQty,missingPrice:missingPrice};
}
function vInvOpen(){var s=vInvStats(),zone='';try{zone=spName(DB.space);}catch(e){}document.getElementById('vInvContext').innerHTML='<b>'+esc(siteName(DB.site))+' &middot; '+esc(zone)+'</b><br>'+s.counted+'/'+s.rows.length+' r&eacute;f&eacute;rences compt&eacute;es &middot; '+s.orders+' &agrave; commander.';document.body.classList.add('vinv-open');document.getElementById('vInvSheet').setAttribute('aria-hidden','false');document.getElementById('vInvAnswer').classList.remove('on');setTimeout(function(){document.querySelector('#vInvSheet .vinv-q button').focus();},30)}
function vInvClose(){document.body.classList.remove('vinv-open');document.getElementById('vInvSheet').setAttribute('aria-hidden','true');document.getElementById('vInvBtn').focus()}
function vInvAnswer(k){var s=vInvStats(),t='';if(k==='next')t=s.first?'<strong>Prochaine r&eacute;f&eacute;rence&nbsp;: '+esc(s.first.p.name)+'</strong>Elle n&rsquo;a pas encore &eacute;t&eacute; compt&eacute;e dans '+esc(spName(s.first.space))+'. Saisissez ce qu&rsquo;il reste r&eacute;ellement&nbsp;; Vera ne transforme jamais une case vide en z&eacute;ro.':'<strong>Le comptage actif est complet.</strong>V&eacute;rifiez maintenant les lignes &agrave; commander, puis enregistrez l&rsquo;inventaire.';else if(k==='check')t=(s.missingQty||s.missingPrice)?'<strong>Vera a trouv&eacute; '+s.missingQty+' quantit&eacute;(s) et '+s.missingPrice+' prix &agrave; compl&eacute;ter.</strong>Ce ne sont pas des z&eacute;ros&nbsp;: la valorisation reste partielle jusqu&rsquo;&agrave; leur saisie. Les '+s.orders+' lignes &agrave; commander sont calcul&eacute;es uniquement avec les valeurs connues.':'<strong>Aucune incoh&eacute;rence de compl&eacute;tude sur le site actif.</strong>Toutes les quantit&eacute;s et tous les prix sont renseign&eacute;s. Contr&ocirc;lez encore visuellement les unit&eacute;s avant d&rsquo;enregistrer.';else if(k==='value')t='<strong>'+s.priced+'/'+s.rows.length+' r&eacute;f&eacute;rences ont un prix d&rsquo;achat.</strong>'+(s.priced===s.rows.length?'La valeur affich&eacute;e peut &ecirc;tre compl&egrave;te si toutes les quantit&eacute;s sont compt&eacute;es.':'La valeur reste partielle. Ajoutez les prix manquants&nbsp;: Vera ne les estime pas.');else t='<strong>Le transfert garde le bon &eacute;tablissement.</strong>Ouvrez Statistiques, enregistrez l&rsquo;inventaire puis choisissez &laquo;&nbsp;Envoyer &agrave; Verdict&nbsp;&raquo;. Le premier comptage reste une base, pas une consommation invent&eacute;e.';var e=document.getElementById('vInvAnswer');e.innerHTML=t;e.classList.add('on')}
function vInvDock(){
  var btn=document.getElementById('vInvBtn'),nav=document.querySelector('nav');
  if(!btn||!nav)return;
  btn.classList.add('vinv-docked');
  if(!btn.querySelector('.vinv-label')){
    var label=document.createElement('span');label.className='vinv-label';label.textContent='Vera';btn.appendChild(label);
  }
  if(btn.parentNode!==nav)nav.appendChild(btn);
}
vInvDock();
veraInventoryApplySeason();
document.addEventListener('keydown',function(e){if(e.key==='Escape'&&document.body.classList.contains('vinv-open'))vInvClose()});
